import{_ as t,o as n,c as s,ag as o}from"./chunks/framework.ySAk_w31.js";const m=JSON.parse(`{"title":"Cadrer avant de coder","description":"","frontmatter":{},"headers":[],"relativePath":"handout-02-cadrer-avant-de-coder.md","filePath":"handout-02-cadrer-avant-de-coder.md","handout":{"fichier":"handout-02-cadrer-avant-de-coder.md","markdown":"# Handout — Cadrer avant de coder\\n\\n**Développeur IA — Foundation · Zenika · fiche module 2**\\n\\nL'agent ne sait que ce qu'on lui donne : cette fiche reprend le module 2 dans l'ordre des slides, et dit quoi lui donner avant qu'il touche au code.\\n\\n## La context window d'un agent de code\\n\\n_Module 2 · slide « La context window d'un agent de code »_\\n\\nC'est **tout** ce que le modèle voit quand il répond :\\n\\n| Bloc                       | Ce qu'il contient                                                                          | Chargé                                                  |\\n| -------------------------- | ------------------------------------------------------------------------------------------ | ------------------------------------------------------- |\\n| **System prompt**          | les consignes du harness : rôle, règles de sécurité, format des réponses                   | à chaque appel                                          |\\n| **Tool definitions**       | la description de chaque tool exposé (lire, écrire, lancer une commande, MCP)              | à chaque appel, avant même le premier message           |\\n| **Instructions projet**    | le fichier d'instructions du dépôt et les skills chargées : conventions, commandes, pièges | à chaque session (les skills, à la demande)             |\\n| **Conversation**           | vos messages, les réponses, les corrections et les décisions                               | renvoyée à chaque appel                                 |\\n| **Tool calls + résultats** | fichiers lus, sorties de commandes, logs d'erreur, résultats de tests                      | le bloc qui grossit le plus vite                        |\\n| **Espace libre**           | la place qui reste avant la compaction                                                     | quand elle rétrécit, la qualité baisse et le coût monte |\\n\\n> Chaque tool exposé, chaque fichier lu, chaque sortie de commande **consomme du budget**.\\n\\nUne demande ciblée donne exactement ce dont l'agent a besoin, ni plus ni moins. À éviter : « Ajoute la pagination à l'API » en collant tout le dépôt. À la place : l'objectif, les fichiers clés, l'invariant et la commande de vérification.\\n\\n## Vue d'ensemble : l'agent de code\\n\\n_Module 2 · slide « Vue d'ensemble : l'agent de code »_\\n\\nLe trajet d'une demande, du haut vers le bas :\\n\\n1. **Toi** : tu demandes, tu valides aux points clés, tu relis le diff.\\n2. **Le harness** assemble la context window (les blocs ci-dessus) et l'envoie au LLM à chaque appel.\\n3. **Le LLM** prédit la suite : soit il répond, soit il écrit une **demande d'action** (« lis bookings.controller.ts », « lance npm test »).\\n4. **Le harness** vérifie les **permissions**, exécute le tool et remet la sortie dans la context window.\\n5. La boucle tourne jusqu'à l'objectif.\\n\\n| Tools, exécutés par le harness | Pour…                                  |\\n| ------------------------------ | -------------------------------------- |\\n| **Fichiers**                   | lire la code base, morceau par morceau |\\n| **Terminal**                   | tests, git                             |\\n| **Serveurs MCP**               | tickets, base, documentation           |\\n\\n> Le LLM est au centre, mais il ne touche à rien : tout ce qu'il « sait » vient de la context window, tout ce qu'il « fait » passe par les tools et les permissions.\\n\\n## Instructions projet (\`AGENTS.md\`)\\n\\n_Module 2 · slide « Instructions projet (AGENTS.md) »_\\n\\nUn fichier **versionné** à la racine, **chargé à chaque session** : conventions, commandes, pièges. **Court**, avec des règles **vérifiables**.\\n\\n| Vague                     | Concret                             |\\n| ------------------------- | ----------------------------------- |\\n| « Formate proprement »    | « Indentation 2 espaces »           |\\n| « Teste tes changements » | « npm test avant chaque commit »    |\\n| « Range le code »         | « Handlers dans src/api/handlers/ » |\\n\\n- **Court** : quelques centaines de lignes au plus ; au-delà, l'adhérence chute. Chaque ligne est relue à chaque appel : elle doit mériter sa place.\\n- C'est du **contexte**, pas une configuration imposée : l'agent essaie de le suivre. Des règles spécifiques et non contradictoires sont mieux respectées.\\n- \`AGENTS.md\` est un format ouvert, lu par la plupart des harness ; certains ont leur propre nom de fichier (voir « Où ça se règle dans mon outil »).\\n\\n### Le générer, puis le relire\\n\\n1. **L'agent analyse le dépôt et propose** un premier jet.\\n2. **Relire** : les concepts métier sont-ils bien identifiés ? les invariants captés ? quelque chose d'halluciné ?\\n3. **Élaguer** ce qui se déduit du code : l'arborescence et la stack, l'agent les retrouve tout seul.\\n4. **Ajouter les pièges connus** : votre expertise.\\n\\n> La génération donne un **point de départ**. Votre expertise **comble les trous**, surtout les pièges.\\n\\n## Une demande initiale bien cadrée\\n\\n_Module 2 · slide « Une demande initiale bien cadrée »_\\n\\n- Le **premier message** de la session : il oriente **toute la suite**.\\n- **Court et relu** : objectif, fichiers, invariants, vérification.\\n- Les noms sont des **ancres** : un chemin, une commande, un invariant orientent l'attention vers tout un bloc de code.\\n- Les **invariants** réduisent les sorties plausibles mais mauvaises.\\n\\n\`\`\`text\\nPagine GET /bookings par curseur.\\nPars de bookings.controller.ts et de shared/pagination.\\nFais évoluer le contrat OpenAPI, garde le schéma Page.\\nFini quand npm test -- bookings passe.\\n\`\`\`\\n\\nDans un code inconnu, on ne sait pas l'écrire seul : l'agent explore et propose les fichiers, commandes et pièges, le dev corrige. Pour une **tâche longue**, on écrit la demande dans un **fichier**, rechargé à chaque session : fichiers clés, commandes, invariants, pièges connus.\\n\\n## Planifier avant de coder\\n\\n_Module 2 · slide « Planifier avant de coder »_\\n\\nL'erreur n° 1 : se jeter **directement dans la génération**. Le **mode plan** des harness explore et propose, sans modifier de fichier.\\n\\n| Étape              | Ce qui se passe                                                                    | Exemple                                                                                                 |\\n| ------------------ | ---------------------------------------------------------------------------------- | ------------------------------------------------------------------------------------------------------- |\\n| 1. **Besoin flou** | le ticket tel qu'on le formule en une phrase                                       | « Pagine /bookings. »                                                                                   |\\n| 2. **Plan relu**   | l'agent propose la demande cadrée et les étapes ; vous les corrigez et les validez | 4 étapes vérifiables, réponse \`{ items, nextCursor }\`, contrat OpenAPI mis à jour, schéma Page inchangé |\\n| 3. **Code**        | généré à partir du plan validé, pas du besoin flou                                 | controller + tests, une étape à la fois                                                                 |\\n\\n- Un bon plan : définir le problème, découper en **étapes vérifiables** (pour chacune, on sait dire « c'est fait » : un test qui passe, un fichier qui existe), identifier les contraintes (contrat d'API, sécurité, performance).\\n- Corriger un plan coûte quelques secondes ; corriger le code produit à partir d'un mauvais plan coûte une session.\\n\\n> On demande d'abord un **plan**, on le corrige, _puis_ le code : la sortie d'une étape devient le **contexte** de la suivante.\\n\\n## Niveaux d'autonomie\\n\\n_Module 2 · slide « Modes de pilotage : monter l'autonomie »_\\n\\nTous les harness proposent les **mêmes niveaux d'autonomie**, sous des noms différents : mode plan, demander, accepter les éditions, tout autoriser…\\n\\n| Niveau d'autonomie           | L'agent…                                    | Pour…                             |\\n| ---------------------------- | ------------------------------------------- | --------------------------------- |\\n| **Observer sans agir**       | lit, cherche, propose un plan               | explorer un code inconnu          |\\n| **Demander à chaque action** | attend ton accord à chaque édition          | apprendre à lire ce qu'il propose |\\n| **Agir dans le périmètre**   | modifie les fichiers, demande pour le reste | dérouler un plan validé           |\\n| **Aller au bout seul**       | enchaîne sans rien demander                 | un environnement isolé et jetable |\\n\\n- Un agent qu'on interrompt à chaque commande coûte plus cher qu'il ne rapporte. À l'inverse, monter l'autonomie sans borner les droits expose à tout ce qu'il peut toucher.\\n- Progression saine : approbation systématique au début, puis on lit le diff plutôt que chaque commande, et jamais « aller au bout seul » sans isolation (conteneur, VM).\\n- Autonomie et périmètre de droits sont **deux réglages distincts**.\\n\\n> On monte d'un niveau quand on fait confiance au **périmètre**, avec un **filet** : tests, commits fréquents, diff relu.\\n\\n## À retenir\\n\\n1. **Instructions projet** : chaque session, courtes, vérifiables.\\n2. **Demande initiale** : la tâche du jour, avec objectif, fichiers, invariants, vérification.\\n3. **Plan** : des étapes vérifiables, relues avant le code.\\n4. **Autonomie** : réglée par niveaux, avec un filet.\\n\\n**Mots-clés** : context window, system prompt, tool definitions, instructions projet, demande initiale, invariant, plan d'exécution, autorégression, niveau d'autonomie, permissions, human-in-the-loop — voir le glossaire.\\n"}}`),a={name:"handout-02-cadrer-avant-de-coder.md"};function r(i,e,l,d,u,c){return n(),s("div",null,[...e[0]||(e[0]=[o(`<p class="zh-type">fiche module 2</p><h1 id="handout-cadrer-avant-de-coder" tabindex="-1">Cadrer avant de coder <a class="header-anchor" href="#handout-cadrer-avant-de-coder" aria-label="Permalink to &quot;Handout — Cadrer avant de coder&quot;">​</a></h1><p>L’agent ne sait que ce qu’on lui donne : cette fiche reprend le module 2 dans l’ordre des slides, et dit quoi lui donner avant qu’il touche au code.</p><h2 id="la-context-window-d-un-agent-de-code" tabindex="-1">La context window d’un agent de code <a class="header-anchor" href="#la-context-window-d-un-agent-de-code" aria-label="Permalink to &quot;La context window d&#39;un agent de code&quot;">​</a></h2><p><em>Module 2 · slide « La context window d’un agent de code »</em></p><p>C’est <strong>tout</strong> ce que le modèle voit quand il répond :</p><table tabindex="0"><thead><tr><th>Bloc</th><th>Ce qu’il contient</th><th>Chargé</th></tr></thead><tbody><tr><td><strong>System prompt</strong></td><td>les consignes du harness : rôle, règles de sécurité, format des réponses</td><td>à chaque appel</td></tr><tr><td><strong>Tool definitions</strong></td><td>la description de chaque tool exposé (lire, écrire, lancer une commande, MCP)</td><td>à chaque appel, avant même le premier message</td></tr><tr><td><strong>Instructions projet</strong></td><td>le fichier d’instructions du dépôt et les skills chargées : conventions, commandes, pièges</td><td>à chaque session (les skills, à la demande)</td></tr><tr><td><strong>Conversation</strong></td><td>vos messages, les réponses, les corrections et les décisions</td><td>renvoyée à chaque appel</td></tr><tr><td><strong>Tool calls + résultats</strong></td><td>fichiers lus, sorties de commandes, logs d’erreur, résultats de tests</td><td>le bloc qui grossit le plus vite</td></tr><tr><td><strong>Espace libre</strong></td><td>la place qui reste avant la compaction</td><td>quand elle rétrécit, la qualité baisse et le coût monte</td></tr></tbody></table><blockquote><p>Chaque tool exposé, chaque fichier lu, chaque sortie de commande <strong>consomme du budget</strong>.</p></blockquote><p>Une demande ciblée donne exactement ce dont l’agent a besoin, ni plus ni moins. À éviter : « Ajoute la pagination à l’API » en collant tout le dépôt. À la place : l’objectif, les fichiers clés, l’invariant et la commande de vérification.</p><h2 id="vue-d-ensemble-l-agent-de-code" tabindex="-1">Vue d’ensemble : l’agent de code <a class="header-anchor" href="#vue-d-ensemble-l-agent-de-code" aria-label="Permalink to &quot;Vue d&#39;ensemble : l&#39;agent de code&quot;">​</a></h2><p><em>Module 2 · slide « Vue d’ensemble : l’agent de code »</em></p><p>Le trajet d’une demande, du haut vers le bas :</p><ol><li><strong>Toi</strong> : tu demandes, tu valides aux points clés, tu relis le diff.</li><li><strong>Le harness</strong> assemble la context window (les blocs ci-dessus) et l’envoie au LLM à chaque appel.</li><li><strong>Le LLM</strong> prédit la suite : soit il répond, soit il écrit une <strong>demande d’action</strong> (« lis bookings.controller.ts », « lance npm test »).</li><li><strong>Le harness</strong> vérifie les <strong>permissions</strong>, exécute le tool et remet la sortie dans la context window.</li><li>La boucle tourne jusqu’à l’objectif.</li></ol><table tabindex="0"><thead><tr><th>Tools, exécutés par le harness</th><th>Pour…</th></tr></thead><tbody><tr><td><strong>Fichiers</strong></td><td>lire la code base, morceau par morceau</td></tr><tr><td><strong>Terminal</strong></td><td>tests, git</td></tr><tr><td><strong>Serveurs MCP</strong></td><td>tickets, base, documentation</td></tr></tbody></table><blockquote><p>Le LLM est au centre, mais il ne touche à rien : tout ce qu’il « sait » vient de la context window, tout ce qu’il « fait » passe par les tools et les permissions.</p></blockquote><h2 id="instructions-projet" tabindex="-1">Instructions projet (<code>AGENTS.md</code>) <a class="header-anchor" href="#instructions-projet" aria-label="Permalink to &quot;Instructions projet (\`AGENTS.md\`)&quot;">​</a></h2><p><em>Module 2 · slide « Instructions projet (AGENTS.md) »</em></p><p>Un fichier <strong>versionné</strong> à la racine, <strong>chargé à chaque session</strong> : conventions, commandes, pièges. <strong>Court</strong>, avec des règles <strong>vérifiables</strong>.</p><table tabindex="0"><thead><tr><th>Vague</th><th>Concret</th></tr></thead><tbody><tr><td>« Formate proprement »</td><td>« Indentation 2 espaces »</td></tr><tr><td>« Teste tes changements »</td><td>« npm test avant chaque commit »</td></tr><tr><td>« Range le code »</td><td>« Handlers dans src/api/handlers/ »</td></tr></tbody></table><ul><li><strong>Court</strong> : quelques centaines de lignes au plus ; au-delà, l’adhérence chute. Chaque ligne est relue à chaque appel : elle doit mériter sa place.</li><li>C’est du <strong>contexte</strong>, pas une configuration imposée : l’agent essaie de le suivre. Des règles spécifiques et non contradictoires sont mieux respectées.</li><li><code>AGENTS.md</code> est un format ouvert, lu par la plupart des harness ; certains ont leur propre nom de fichier (voir « Où ça se règle dans mon outil »).</li></ul><h3 id="le-generer-puis-le-relire" tabindex="-1">Le générer, puis le relire <a class="header-anchor" href="#le-generer-puis-le-relire" aria-label="Permalink to &quot;Le générer, puis le relire&quot;">​</a></h3><ol><li><strong>L’agent analyse le dépôt et propose</strong> un premier jet.</li><li><strong>Relire</strong> : les concepts métier sont-ils bien identifiés ? les invariants captés ? quelque chose d’halluciné ?</li><li><strong>Élaguer</strong> ce qui se déduit du code : l’arborescence et la stack, l’agent les retrouve tout seul.</li><li><strong>Ajouter les pièges connus</strong> : votre expertise.</li></ol><blockquote><p>La génération donne un <strong>point de départ</strong>. Votre expertise <strong>comble les trous</strong>, surtout les pièges.</p></blockquote><h2 id="une-demande-initiale-bien-cadree" tabindex="-1">Une demande initiale bien cadrée <a class="header-anchor" href="#une-demande-initiale-bien-cadree" aria-label="Permalink to &quot;Une demande initiale bien cadrée&quot;">​</a></h2><p><em>Module 2 · slide « Une demande initiale bien cadrée »</em></p><ul><li>Le <strong>premier message</strong> de la session : il oriente <strong>toute la suite</strong>.</li><li><strong>Court et relu</strong> : objectif, fichiers, invariants, vérification.</li><li>Les noms sont des <strong>ancres</strong> : un chemin, une commande, un invariant orientent l’attention vers tout un bloc de code.</li><li>Les <strong>invariants</strong> réduisent les sorties plausibles mais mauvaises.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pagine GET /bookings par curseur.</span></span>
<span class="line"><span>Pars de bookings.controller.ts et de shared/pagination.</span></span>
<span class="line"><span>Fais évoluer le contrat OpenAPI, garde le schéma Page.</span></span>
<span class="line"><span>Fini quand npm test -- bookings passe.</span></span></code></pre></div><p>Dans un code inconnu, on ne sait pas l’écrire seul : l’agent explore et propose les fichiers, commandes et pièges, le dev corrige. Pour une <strong>tâche longue</strong>, on écrit la demande dans un <strong>fichier</strong>, rechargé à chaque session : fichiers clés, commandes, invariants, pièges connus.</p><h2 id="planifier-avant-de-coder" tabindex="-1">Planifier avant de coder <a class="header-anchor" href="#planifier-avant-de-coder" aria-label="Permalink to &quot;Planifier avant de coder&quot;">​</a></h2><p><em>Module 2 · slide « Planifier avant de coder »</em></p><p>L’erreur n° 1 : se jeter <strong>directement dans la génération</strong>. Le <strong>mode plan</strong> des harness explore et propose, sans modifier de fichier.</p><table tabindex="0"><thead><tr><th>Étape</th><th>Ce qui se passe</th><th>Exemple</th></tr></thead><tbody><tr><td>1. <strong>Besoin flou</strong></td><td>le ticket tel qu’on le formule en une phrase</td><td>« Pagine /bookings. »</td></tr><tr><td>2. <strong>Plan relu</strong></td><td>l’agent propose la demande cadrée et les étapes ; vous les corrigez et les validez</td><td>4 étapes vérifiables, réponse <code>{ items, nextCursor }</code>, contrat OpenAPI mis à jour, schéma Page inchangé</td></tr><tr><td>3. <strong>Code</strong></td><td>généré à partir du plan validé, pas du besoin flou</td><td>controller + tests, une étape à la fois</td></tr></tbody></table><ul><li>Un bon plan : définir le problème, découper en <strong>étapes vérifiables</strong> (pour chacune, on sait dire « c’est fait » : un test qui passe, un fichier qui existe), identifier les contraintes (contrat d’API, sécurité, performance).</li><li>Corriger un plan coûte quelques secondes ; corriger le code produit à partir d’un mauvais plan coûte une session.</li></ul><blockquote><p>On demande d’abord un <strong>plan</strong>, on le corrige, <em>puis</em> le code : la sortie d’une étape devient le <strong>contexte</strong> de la suivante.</p></blockquote><h2 id="niveaux-d-autonomie" tabindex="-1">Niveaux d’autonomie <a class="header-anchor" href="#niveaux-d-autonomie" aria-label="Permalink to &quot;Niveaux d&#39;autonomie&quot;">​</a></h2><p><em>Module 2 · slide « Modes de pilotage : monter l’autonomie »</em></p><p>Tous les harness proposent les <strong>mêmes niveaux d’autonomie</strong>, sous des noms différents : mode plan, demander, accepter les éditions, tout autoriser…</p><table tabindex="0"><thead><tr><th>Niveau d’autonomie</th><th>L’agent…</th><th>Pour…</th></tr></thead><tbody><tr><td><strong>Observer sans agir</strong></td><td>lit, cherche, propose un plan</td><td>explorer un code inconnu</td></tr><tr><td><strong>Demander à chaque action</strong></td><td>attend ton accord à chaque édition</td><td>apprendre à lire ce qu’il propose</td></tr><tr><td><strong>Agir dans le périmètre</strong></td><td>modifie les fichiers, demande pour le reste</td><td>dérouler un plan validé</td></tr><tr><td><strong>Aller au bout seul</strong></td><td>enchaîne sans rien demander</td><td>un environnement isolé et jetable</td></tr></tbody></table><ul><li>Un agent qu’on interrompt à chaque commande coûte plus cher qu’il ne rapporte. À l’inverse, monter l’autonomie sans borner les droits expose à tout ce qu’il peut toucher.</li><li>Progression saine : approbation systématique au début, puis on lit le diff plutôt que chaque commande, et jamais « aller au bout seul » sans isolation (conteneur, VM).</li><li>Autonomie et périmètre de droits sont <strong>deux réglages distincts</strong>.</li></ul><blockquote><p>On monte d’un niveau quand on fait confiance au <strong>périmètre</strong>, avec un <strong>filet</strong> : tests, commits fréquents, diff relu.</p></blockquote><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li><strong>Instructions projet</strong> : chaque session, courtes, vérifiables.</li><li><strong>Demande initiale</strong> : la tâche du jour, avec objectif, fichiers, invariants, vérification.</li><li><strong>Plan</strong> : des étapes vérifiables, relues avant le code.</li><li><strong>Autonomie</strong> : réglée par niveaux, avec un filet.</li></ol><p><strong>Mots-clés</strong> : context window, system prompt, tool definitions, instructions projet, demande initiale, invariant, plan d’exécution, autorégression, niveau d’autonomie, permissions, human-in-the-loop — voir le glossaire.</p>`,43)])])}const g=t(a,[["render",r]]);export{m as __pageData,g as default};
